window.docContents[6].resolve({"/Development-Server/#serve-options":{"contents":"A single optional positional argument is accepted, which is the directory to be served at /.\nIt defaults to the current directory unless a configuration file is provided.\nIf the configuration file defines mounts, then the positional argument is rejected.\nThe following options are also accepted:\n\n --port PORT, -p PORT\n\nThe port to listen on. Defaults to 8000.\n\n --strict-port\n\nFail if the port is in use instead of trying another.\n\n --config FILE\n\nLoad configuration from FILE. Defaults to ./verso-serve.toml if it exists.\n  If no configuration file is provided, the default values for the configuration format are used.\n\n --quiet\n\nSuppress per-request logging.\n\n --verbose, -v\n\nLog additional detail.\n\n --help, -h\n\nShow usage and exit.\n\n\n\nCommand-line options override values from the configuration file.\n\n","context":"Writing Documentation in Lean with Verso\u0009Development Server","header":"9.2. Command-Line Options","id":"/Development-Server/#serve-options"}});